<style lang="scss" scoped>
@import "../style.scss";

.Loading {
  display: flex;
  justify-content: center;
  align-items: center;

  &__Spinner {
    display: flex;
    justify-content: center;
    align-items: center;
    animation: spinning 1.1s infinite linear;

    @keyframes spinning {
      0% {
        transform: rotate(0deg);
      }
      100% {
        transform: rotate(360deg);
      }
    }
  }
}
</style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";

@Component({
  components: {
    Icon,
  },
})
export default class Loading extends Vue {
  @Prop({
    type: Boolean,
    default: false,
  })
  loading;

  @Prop({
    type: Number,
    default: 24,
  })
  size;

  @Prop({
    type: String,
    default: "black",
  })
  color;

  get IconShape() {
    return IconShape;
  }
}
</script>

<template>
  <div class="Loading" aria-live="polite" :aria-busy="loading.toString()">
    <div class="Loading__Spinner">
      <Icon
        v-if="loading"
        :shape="IconShape.T_CIRCLE_DASHED"
        :size="size"
        :color="color"
      />
    </div>
    <p class="visually-hidden">
      {{ loading ? "Content is loading" : "Content has finished loading." }}
    </p>
  </div>
</template>
